import { EdgeTTS } from 'edge-tts-universal';

export interface TTSOptions {
  voice?: string;
  pitch?: number;
  rate?: number;
  volume?: number;
}

export class TTSService {
  private audioContext: AudioContext | null = null;

  private getAudioContext(): AudioContext {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return this.audioContext;
  }

  async speak(text: string, options: TTSOptions = {}): Promise<void> {
    try {
      // Use provided options or defaults
      const voice = options.voice || 'en-US-JennyNeural';
      const pitch = options.pitch !== undefined ? options.pitch : -5;
      const rate = options.rate !== undefined ? options.rate : 1;
      const volume = options.volume !== undefined ? options.volume : 1;

      const audioData = await (EdgeTTS as any)(text, {
        voice,
        pitch: `${pitch >= 0 ? '+' : ''}${pitch}Hz`,
        rate: `${rate >= 1 ? '+' : ''}${Math.round((rate - 1) * 100)}%`,
        volume: `${volume >= 1 ? '+' : ''}${Math.round((volume - 1) * 100)}%`,
      });

      const audioContext = this.getAudioContext();

      // Handle different audio data formats
      let arrayBuffer: ArrayBuffer;
      if (audioData instanceof ArrayBuffer) {
        arrayBuffer = audioData;
      } else if (audioData instanceof Blob) {
        arrayBuffer = await audioData.arrayBuffer();
      } else if (audioData && audioData.audio && audioData.audio instanceof Blob) {
        arrayBuffer = await audioData.audio.arrayBuffer();
      } else if (audioData && audioData.buffer) {
        arrayBuffer = audioData.buffer.slice(audioData.byteOffset, audioData.byteOffset + audioData.byteLength);
      } else {
        console.error('Unknown audioData type:', typeof audioData, audioData);
        throw new Error('Unsupported audio data format from TTS');
      }

      const buffer = await audioContext.decodeAudioData(arrayBuffer);

      const source = audioContext.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContext.destination);

      return new Promise<void>((resolve) => {
        source.onended = () => resolve();
        source.start();
      });
    } catch (error) {
      console.error('TTS synthesis error:', error);
      throw error;
    }
  }
}

export const ttsService = new TTSService();
